import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const root='./LOCAL_USER/AppData/Local/FVI-QA-Private-20260925';
const vault=await readFile('./.private/CREDENTIALS.md','utf8');
const a=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_BEGIN -->'),b=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_END -->');if(a<0||b<=a)throw Error('Canonical credential markers absent');
const token=vault.slice(a,b).split(/\r?\n/).find(x=>/^\|\s*`SUPABASE_ACCESS_TOKEN`\s*\|/.test(x))?.split('|')[2]?.trim().replace(/^`|`$/g,'');if(!/^sbp_[A-Za-z0-9_-]{20,}$/.test(token??''))throw Error('Management access unavailable');
const tables=['business_units','business_unit_users','business_unit_members','tenant_groups','tenant_group_members','tenant_group_roles','tenant_members','tenant_environments','workspace_members','workspaces','access_review_campaigns','access_review_items','soc2_access_reviews','audit_log','rbac_roles','rbac_role_permissions','user_roles','platform_roles','tenants','profiles','bu_group_assignments','bu_user_assignments','data_resource_bu_grants','data_resource_registry','data_resource_registry_grants','data_resource_registry_owner_bu','effective_user_permissions','rbac_user_grants','recon_definition_bu_grants','recon_definition_business_units','recon_definitions','recon_permissions','team_members','teams'];
const names=tables.map(n=>`'${n}'`).join(',');
const query=`SELECT jsonb_build_object(
'ledger',(SELECT jsonb_build_object('count',count(*),'latest',max(version::text)) FROM supabase_migrations.schema_migrations),
'engine',current_setting('server_version_num'),
'tables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN (${names})),
'columns',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',at.attname,'position',at.attnum,'type',format_type(at.atttypid,at.atttypmod),'not_null',at.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',at.attacl::text,'identity',at.attidentity,'generated',at.attgenerated) ORDER BY c.relname,at.attnum) FROM pg_attribute at JOIN pg_class c ON c.oid=at.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=at.attnum WHERE n.nspname='public' AND c.relname IN (${names}) AND at.attnum>0 AND NOT at.attisdropped),
'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.conname,'type',t.contype,'validated',t.convalidated,'definition',pg_get_constraintdef(t.oid)) ORDER BY c.relname,t.conname) FROM pg_constraint t JOIN pg_class c ON c.oid=t.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN (${names})),
'indexes',(SELECT jsonb_agg(to_jsonb(i) ORDER BY tablename,indexname) FROM pg_indexes i WHERE schemaname='public' AND tablename IN (${names})),
'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname) FROM pg_policies p WHERE schemaname='public' AND tablename IN (${names})),
'triggers',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid),'helper',pg_get_functiondef(t.tgfoid)) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN (${names}) AND NOT t.tgisinternal),
'helpers',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'definition',pg_get_functiondef(p.oid)) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind='f' AND ((n.nspname='auth' AND p.proname IN ('uid','role','jwt')) OR(n.nspname IN ('public','private') AND (p.proname IN ('can_admin_tenant','has_tenant_role','is_tenant_member','is_tenant_admin','is_platform_admin','user_has_permission','user_bu_scope','resolve_user_permissions','resolve_user_permissions_effective','tenant_admin_touch_updated_at','record_audit_event') OR p.proname LIKE '%group%member%' OR p.proname LIKE '%membership%request%' OR p.proname LIKE '%access_review%')))),
'permissions',(SELECT jsonb_agg(to_jsonb(p) ORDER BY id) FROM public.permissions p WHERE id LIKE 'tenant.%' OR id IN ('audit.log.read','compliance.access_review.attest')),
'new_function_conflicts',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid)) ORDER BY n.nspname,p.proname),'[]') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private') AND p.proname LIKE 'governance_%')
) AS catalog;`;
await writeFile(`${root}/FVI-GOVERNANCE-CATALOG-QUERY-EXTENDED-20261002.sql`,query);
for(const [environment,ref] of [['PROD','YOUR_PROJECT_REF'],['DEV','YOUR_PROJECT_REF']]){
 const response=await fetch(`https://api.supabase.com/v1/projects/${ref}/database/query`,{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json'},body:JSON.stringify({read_only:true,query}),signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error(`${environment} HTTP${response.status}, body withheld`);
 const rows=await response.json(),c=rows?.[0]?.catalog;if(!c?.ledger||!c.tables)throw Error('Actual governance catalog absent');
 const file=`${root}/FVI-GOVERNANCE-CATALOG-${environment}-EXTENDED-20261002.json`,bytes=JSON.stringify({at:new Date().toISOString(),ref,read_only:true,query,rows},null,2);await writeFile(file,bytes);
 console.log(JSON.stringify({environment,http:response.status,file,sha256:createHash('sha256').update(bytes).digest('hex'),ledger:c.ledger,engine:c.engine,relations:c.tables.map(t=>t.name),columns:c.columns.length,policies:c.policies.length,helpers:c.helpers.length,permissionCount:c.permissions.length,newFunctionConflicts:c.new_function_conflicts.length}));
}
